-- Storefront schema (Oracle 19c)
CREATE SEQUENCE PRODUCTS_SEQ START WITH 1 INCREMENT BY 1;

CREATE TABLE PRODUCTS (
  PRODUCT_ID   NUMBER(19)     PRIMARY KEY,
  SKU          VARCHAR2(40)   NOT NULL UNIQUE,
  NAME         VARCHAR2(200)  NOT NULL,
  DESCRIPTION  CLOB,
  CATEGORY     VARCHAR2(60),
  BRAND        VARCHAR2(60),
  PRICE        NUMBER(12,2),
  STOCK_QTY    NUMBER(10)     DEFAULT 0,
  ACTIVE       NUMBER(1)      DEFAULT 1 CHECK (ACTIVE IN (0, 1)),
  UPDATED_AT   TIMESTAMP      DEFAULT SYSTIMESTAMP
);

CREATE TABLE ORDER_LINES (
  LINE_ID      NUMBER(19)     PRIMARY KEY,
  PRODUCT_ID   NUMBER(19)     REFERENCES PRODUCTS (PRODUCT_ID),
  QTY          NUMBER(6)      NOT NULL,
  ORDERED_AT   DATE           DEFAULT SYSDATE
);

CREATE OR REPLACE TRIGGER PRODUCTS_TOUCH
  BEFORE UPDATE ON PRODUCTS FOR EACH ROW
BEGIN
  :NEW.UPDATED_AT := SYSTIMESTAMP;
END;
/

CREATE MATERIALIZED VIEW PRODUCT_SALES_MV
  BUILD IMMEDIATE REFRESH COMPLETE ON DEMAND AS
  SELECT PRODUCT_ID, SUM(QTY) SOLD FROM ORDER_LINES GROUP BY PRODUCT_ID;
